const listPromotionGateNames = `-- name: ListPromotionGateNames :many
SELECT gate_name
FROM promotion_gates
WHERE promotion_id = $1
ORDER BY attachment_order
`

func (q *Queries) ListPromotionGateNames(ctx context.Context, promotionID pgtype.UUID) ([]string, error) {
	rows, err := q.db.Query(ctx, listPromotionGateNames, promotionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var gate_name string
		if err := rows.Scan(&gate_name); err != nil {
			return nil, err
		}
		items = append(items, gate_name)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listPromotionReviews = `-- name: ListPromotionReviews :many
SELECT id, integration, external_promotion_id, request_digest, stage_id, stage_snapshot, repository_id, repository_snapshot, base_revision, candidate_revision, candidate_branch, target_branch, policy_snapshot, review_required, status, message, preparation_repository_id, preparation_catalog_revision_id, preparation_run_id, git_diff_artifact_id, argo_diff_artifact_id, requested_by_principal_id, requested_by_snapshot, created_at, preparation_completed_at, decided_at, expires_at, updated_at, source, source_stage_id, selected_freight_snapshot, dispatch_attempt_count, next_dispatch_at, last_dispatch_at, dispatched_at, kargo_promotion_uid, next_reconciliation_at, last_reconciliation_at, preparation_failure_count, next_preparation_attempt_at, kargo_outcome_phase, kargo_outcome_observed_at, kargo_outcome_diagnostic, dispatch_failed_at, dispatch_diagnostic, cancellation_requested_at, cancellation_requested_by_id, cancellation_requested_by_snapshot, cancellation_confirmed_at, next_cancel_attempt_at, callback_released, server_gate_release_evidence
FROM promotions
WHERE ($1::uuid IS NULL OR repository_id = $1)
  AND (
      $2::text IS NULL
      OR base_revision = $2
      OR candidate_revision = $2
  )
  AND ($3::text IS NULL OR $3 = CASE
      WHEN cancellation_requested_at IS NULL THEN 'not-requested'
      WHEN cancellation_confirmed_at IS NOT NULL THEN 'completed'
      WHEN kargo_outcome_phase IS NOT NULL OR dispatch_failed_at IS NOT NULL THEN 'overtaken'
      ELSE 'requested' END)
  AND ($4::text IS NULL OR status = $4)
  AND (
      $5::text IS NULL
      OR ($5 = 'not-applicable' AND source = 'kargo')
      OR (
          $5 = 'awaiting-delivery'
          AND source = 'slipramp'
          AND next_dispatch_at IS NOT NULL
          AND dispatched_at IS NULL
          AND dispatch_failed_at IS NULL
      )
      OR ($5 = 'stopped' AND source = 'slipramp' AND next_dispatch_at IS NULL
          AND dispatched_at IS NULL AND dispatch_failed_at IS NULL)
      OR ($5 = 'delivered' AND source = 'slipramp' AND dispatched_at IS NOT NULL)
      OR ($5 = 'failed' AND source = 'slipramp' AND dispatch_failed_at IS NOT NULL)
  )
  AND ($6::text IS NULL OR kargo_outcome_phase = $6)
  AND ($7::text IS NULL OR integration = $7)
  AND ($8::uuid IS NULL OR stage_id = $8)
  AND ($9::text IS NULL OR stage_snapshot->>'cluster' = $9)
  AND ($10::text IS NULL OR stage_snapshot->>'project' = $10)
  AND ($11::text IS NULL OR stage_snapshot #>> '{enrichment,application}' = $11)
ORDER BY (status = 'pending' AND cancellation_requested_at IS NULL) DESC, created_at DESC, id DESC
LIMIT $13
OFFSET $12::bigint
`

