const upsertPromotionStagePolicy = `-- name: UpsertPromotionStagePolicy :one
INSERT INTO promotion_stage_policies (
    stage_id,
    mode,
    expires_at,
    reason,
    updated_by_principal_id,
    updated_by_snapshot,
    updated_at
) SELECT
    $1,
    $2,
    $3,
    $4,
    $5,
    $6,
    $7
WHERE $2::text <> 'review-required'
   OR EXISTS (
       SELECT 1
       FROM promotion_stages
       JOIN repositories
         ON repositories.name = promotion_stages.repository_name
        AND repositories.clone_url = promotion_stages.repository_url
        AND repositories.removed_at IS NULL
       WHERE promotion_stages.id = $1
         AND application <> ''
         AND environment <> ''
         AND repository_name <> ''
         AND repository_url <> ''
         AND target_branch <> ''
         AND cardinality(source_paths) > 0
   )
ON CONFLICT (stage_id) DO UPDATE
SET mode = EXCLUDED.mode,
    expires_at = EXCLUDED.expires_at,
    reason = EXCLUDED.reason,
    updated_by_principal_id = EXCLUDED.updated_by_principal_id,
    updated_by_snapshot = EXCLUDED.updated_by_snapshot,
    updated_at = EXCLUDED.updated_at
WHERE promotion_stage_policies.updated_at <= EXCLUDED.updated_at
RETURNING stage_id, mode, expires_at, reason, updated_by_principal_id, updated_by_snapshot, updated_at
`

type UpsertPromotionStagePolicyParams struct {
	StageID              pgtype.UUID
	Mode                 string
	ExpiresAt            pgtype.Timestamptz
	Reason               *string
	UpdatedByPrincipalID pgtype.UUID
	UpdatedBySnapshot    []byte
	UpdatedAt            pgtype.Timestamptz
}

func (q *Queries) UpsertPromotionStagePolicy(ctx context.Context, arg UpsertPromotionStagePolicyParams) (PromotionStagePolicy, error) {
	row := q.db.QueryRow(ctx, upsertPromotionStagePolicy,
		arg.StageID,
		arg.Mode,
		arg.ExpiresAt,
		arg.Reason,
		arg.UpdatedByPrincipalID,
		arg.UpdatedBySnapshot,
		arg.UpdatedAt,
	)
	var i PromotionStagePolicy
	err := row.Scan(
		&i.StageID,
		&i.Mode,
		&i.ExpiresAt,
		&i.Reason,
		&i.UpdatedByPrincipalID,
		&i.UpdatedBySnapshot,
		&i.UpdatedAt,
	)
	return i, err
}
